  };

  const redactSecrets = text => {
    let result = String(text ?? '');
    const secrets = [state.apiDraft?.key, ...state.apiProfiles.map(profile => profile?.key), databaseApiConfig.apiDraft?.key, ...databaseApiConfig.apiProfiles.map(profile => profile?.key)]
      .filter(value => typeof value === 'string' && value.length >= 4)
