      if (error.status !== undefined) parts.push(`status: ${detail(error.status)}`);
      if (error.statusText) parts.push(`statusText: ${detail(error.statusText)}`);
      if (error.response !== undefined) parts.push(`response: ${detail(error.response)}`);
      if (error.data !== undefined) parts.push(`data: ${detail(error.data)}`);
      if (error.cause !== undefined) parts.push(`cause: ${detail(error.cause)}`);
