  const savedTimeout = readStorage(`${STORAGE_PREFIX}:api-timeout`, TRAINER_API_TIMEOUT_DEFAULT);
  state.aiTimeoutSeconds = Number.isInteger(savedTimeout) && savedTimeout >= 10 && savedTimeout <= 300 ? savedTimeout : TRAINER_API_TIMEOUT_DEFAULT;
  state.apiDraft = state.apiProfiles[0] ? { ...state.apiProfiles[0], key: '' } : { id: '', name: '', apiurl: '', key: '', model: '', source: 'openai' };
  const readTrainerPrompt = (key, fallback, kind) => {
    const saved = readStorage(key, null);
    if (typeof saved !== "string" || !saved.trim()) return fallback;
    const [length, signature] = LEGACY_TRAINER_PROMPT_SIGNATURES[kind];
    if (saved.length !== length) return saved;
    let hash = 2166136261;
    for (let i = 0; i < saved.length; i++) hash = Math.imul(hash ^ saved.charCodeAt(i), 16777619);
