  state.fenglingPrompt = readTrainerPrompt(FENGLING_PROMPT_KEY, FENGLING_SYSTEM_PROMPT, "SYSTEM");
  state.extraPrompt = readTrainerPrompt(EXTRA_PROMPT_KEY, FENGLING_EXTRA_PROMPT, "EXTRA");
  state.personaPrompt = readTrainerPrompt(PERSONA_PROMPT_KEY, FENGLING_PERSONA_PROMPT, "PERSONA");
  const savedBodyCount = Number(readStorage(BODY_COUNT_KEY, 3));
  state.bodyCount = Number.isFinite(savedBodyCount) ? Math.min(20, Math.max(0, Math.trunc(savedBodyCount))) : 3;
  state.lorePresets = readStorage(LORE_PRESETS_KEY, {});
  state.layout = readStorage(LAYOUT_KEY, null);

  // core/values.js
  const clone = value => {
    if (typeof structuredClone === 'function') {
      return structuredClone(value);
    }
    return JSON.parse(JSON.stringify(value));
  };

  const isPlainObject = value =>
    value !== null && Object.prototype.toString.call(value) === '[object Object]';

  const isValueWithDescription = value => Array.isArray(value) && value.length === 2 && typeof value[1] === 'string';

  const logicalValue = (value, schemaNode) => {
    if (isValueWithDescription(value) && schemaNode?.type !== 'array' && typeof state.draft?.schema !== 'string') {
      return value[0];
    }
    return value;
  };

  const descriptionOf = (value, schemaNode) => {
    if (isValueWithDescription(value) && schemaNode?.type !== 'array' && typeof state.draft?.schema !== 'string') {
      return value[1];
    }
    return '';
  };

  const stableStringify = value => {
    const seen = new WeakSet();
    const normalize = current => {
      if (current === null || typeof current !== 'object') return current;
      if (seen.has(current)) throw new TypeError('Dữ liệu MVU chứa tham chiếu vòng lặp');
      seen.add(current);
      if (Array.isArray(current)) return current.map(normalize);
      return Object.keys(current)
        .sort((a, b) => a.localeCompare(b, 'zh-CN'))
        .reduce((result, key) => {
