  // Paths include a physical index 0 when descending through a legacy wrapper.
  const valueAt = (root, path) => path.reduce((current, key) => current?.[key], root);

  const setLogicalValueAt = (root, path, nextValue, schemaNode) => {
    const parent = valueAt(root, path.slice(0, -1));
    const key = path.at(-1);
    const current = parent[key];
    if (logicalValue(current, schemaNode) !== current) {
      current[0] = nextValue;
    } else {
      parent[key] = nextValue;
    }
  };

  const validateSchema = (value, schema) => {
    if (!isPlainObject(schema) || !['object', 'array', 'string', 'number', 'integer', 'boolean', 'null', 'any'].includes(schema.type)) {
      return { available: false, errors: [] };
    }

    const errors = [];
    const visit = (raw, node, path) => {
      if (!node || typeof node !== 'object' || node.type === 'any') return;
      const current = logicalValue(raw, node);
      const location = path.length ? path.join(' › ') : 'Gốc biến';
      if (Array.isArray(node.enum) && !node.enum.some(item => stableStringify(item) === stableStringify(current))) errors.push(`${location} không nằm trong các tùy chọn cho phép`);

      if (node.type === 'object') {
        if (!isPlainObject(current)) {
