        if (typeof node.maximum === 'number' && current > node.maximum) errors.push(`${location} lớn hơn giới hạn trên quy định của schema ${node.maximum}`);
      }
    };

    visit(value, schema, []);
    return { available: true, errors };
  };

  const inspectEntryShape = (rootValue, schema, sourceRoot = null) => {
    const issues = [];
    const scanNewFields = (node, path) => {
      if (issues.length >= 200) return;
      if (isValueWithDescription(node)) return scanNewFields(node[0], path);
      if (isPlainObject(node)) {
        for (const [key, child] of Object.entries(node)) if (!rejectUnsafeSegment(key)) scanNewFields(child, [...path, key]);
      } else if (node === '' || node === null) {
        issues.push({ path, message: 'Thuộc tính này của mục mới vẫn đang để trống, vui lòng xác nhận có cần điền hay không', kind: 'empty' });
      }
    };
    const visit = (node, path, schemaNode) => {
      if (!isPlainObject(node) || path.length > 7 || issues.length >= 200) return;
      if (sourceRoot && path.length >= 2 && valueAt(sourceRoot, path.slice(0, -1)) !== undefined && valueAt(sourceRoot, path) === undefined) {
        scanNewFields(node, path);
      }
      const siblings = Object.entries(node).filter(([key, value]) => !rejectUnsafeSegment(key) && isPlainObject(value));
      if (path.length && siblings.length >= 2) {
        const exemplar = siblings.reduce((best, candidate) => Object.keys(candidate[1]).length > Object.keys(best[1]).length ? candidate : best);
        for (const [name, entry] of siblings) {
          if (name === exemplar[0]) continue;
          if (!Object.keys(entry).some(key => Object.prototype.hasOwnProperty.call(exemplar[1], key))) continue;
          for (const key of Object.keys(exemplar[1])) {
            if (rejectUnsafeSegment(key) || Object.prototype.hasOwnProperty.call(entry, key)) continue;
            issues.push({ path: [...path, name, key], message: 'Mục tham chiếu cùng nhóm có thuộc tính này', kind: 'missing' });
          }
        }
      }
      for (const [key, child] of Object.entries(node)) {
        if (!rejectUnsafeSegment(key) && isPlainObject(child)) visit(child, [...path, key], schemaChild(schemaNode, key));
      }
    };
    visit(rootValue, [], schema);
    const declared = validateSchema(rootValue, schema);
    for (const message of declared.errors) issues.push({ path: [], message, kind: 'schema' });
    return issues;
  };

  const escapeSearchValue = value => {
    try {
      return typeof value === 'string' ? value : JSON.stringify(value);
    } catch {
      return String(value);
    }
  };

  // features/request-retry.js
  const normalizeFenglingRetryCount = value => (typeof value === 'number' || typeof value === 'string' && value.trim() !== '') && Number.isInteger(Number(value)) && Number(value) >= 0 && Number(value) <= 20 ? Number(value) : 0;
  const createFenglingRetryRunner = ({ wait, errorText }) => {
    const stopped = () => { const issue = new Error('Nhiệm vụ đã kết thúc, tầng tin nhắn hoặc cuộc trò chuyện đã chuyển đổi, hoặc ngữ cảnh đã thay đổi, không tiếp tục thử lại'); issue.name = 'AbortError'; return issue; };
    const run = async (generate, request, { retries = 0, active = () => true, validate, progress = () => {} } = {}) => {
      const limit = normalizeFenglingRetryCount(retries), failures = [];
      let lastResponse;
      // Most compatible endpoints accept ordinary JSON but not response_format/json_schema.
      // Local parsers still enforce exactly the same schema, scope and value checks.
      const { json_schema: ignoredSchema, ...compatible } = request;
      for (let attempt = 1; attempt <= limit + 1; attempt++) {
        if (!active()) throw stopped();
        progress({ attempt, retries: limit, waiting: false });
        try {
          const response = await generate(compatible); lastResponse = response;
          if (!active()) throw stopped();
