            const note = /<none>/i.test(details) ? '\nGhi chú: Lỗi upstream do trợ lý chuyển tiếp không có nguyên nhân cụ thể; <none> không phải là mã trạng thái HTTP. Lần này đã dùng yêu cầu JSON thông thường, không ép buộc giao diện xuất cấu trúc.' : '';
