  // features/request-lifecycle.js
  const createFenglingRequestLifecycle = ({ clock, stop, changed = () => {} }) => {
    const pending = new Set();
    const run = async (generate, request, { active = () => true, timeoutMs = 60000, onStop } = {}) => {
      if (!active()) throw Object.assign(new Error('Yêu cầu đã bị hủy hoặc ngữ cảnh đã thay đổi'), { name: 'AbortError' });
      let timeout, watch, rejectRequest, settled = false;
      const fail = (name, message) => {
        if (settled) return;
        settled = true;
        try { Promise.resolve(onStop ? onStop() : stop(request.generation_id)).catch(() => {}); } catch {}
        rejectRequest(Object.assign(new Error(message), { name }));
      };
      const owner = { id: request.generation_id, cancel: () => fail('AbortError', 'Yêu cầu API lần này đã bị hủy, phản hồi đến muộn sẽ không được áp dụng') };
      const interrupted = new Promise((_, reject) => {
        rejectRequest = reject;
        timeout = clock.setTimeout(() => fail('TimeoutError', `Yêu cầu API vượt quá ${Math.round(timeoutMs / 1000)} giây chưa hoàn thành, đã kết thúc chờ đợi; vui lòng kiểm tra giao diện kết nối hoặc điều chỉnh thời gian chờ`), timeoutMs);
