          if (settled) return;
          let current = false; try { current = active(); } catch {}
          if (!current) fail('AbortError', 'Yêu cầu đã bị hủy, tầng tin nhắn hoặc cuộc trò chuyện đã chuyển đổi, phản hồi đến muộn sẽ không được áp dụng');
