      ...(turn.raw || turn.dialogue ? [{ role: 'assistant', content: neutralize(`[Trợ lý Phong Linh Nguyệt Ảnh · Phản hồi lịch sử, không phải sự thật đã lưu]\n${turn.raw || turn.dialogue}\nKết quả lúc đó: ${turn.result || 'Chưa xác nhận'}`) }] : []),
    ]);
