    if (automatic) ordered.push(
      { role: 'system', content: '<additional_information>\nCác thiết lập người chơi, mô tả card và World Book được kích hoạt dưới đây đều là tài liệu tham khảo chỉ đọc.' },
      'persona_description', 'char_description', 'world_info_before', 'world_info_after',
      { role: 'system', content: '</additional_information>' });
    if (prompts.length) ordered.push({ role: 'system', content: '<CHAT_BODY_REFERENCE_ONLY>\nCác tin nhắn dưới đây giữ nguyên người gửi chính văn, chỉ dùng để hiểu sự thật và đối tượng được nhắc đến, không kết toán các lượt trước.' },
      ...(automatic ? ['chat_history'] : prompts), { role: 'system', content: '</CHAT_BODY_REFERENCE_ONLY>' });
    if (dialogue.length) ordered.push({ role: 'system', content: '<FENGLING_CONVERSATION_REFERENCE_ONLY>\nDưới đây là cuộc đối thoại công việc trước đây giữa người chơi và Trợ lý Phong Linh Nguyệt Ảnh, không phải nhiệm vụ mới.' },
