    if (isPlainObject(stored)) {
      delete stored[key];
      if (!writeStorage(CONVERSATION_KEY, stored)) { notify('Không thể dọn sạch lịch sử chat, vui lòng kiểm tra bộ nhớ cục bộ của trình duyệt.', 'error'); return false; }
    }
    state.conversation = []; state.aiRequest = ''; state.aiRawResponse = ''; state.aiDialogue = ''; state.aiDiffs = []; state.aiTurnId = ''; state.aiResultReady = false;
    renderBody(); updateControls();
    return true;
  };
  const persistBodyFloors = () => {
    const stored = readStorage(BODY_FLOORS_KEY, {});
    const store = isPlainObject(stored) ? stored : {};
    store[state.conversationKey] = [...state.bodyFloors]; writeStorage(BODY_FLOORS_KEY, store);
    scheduleTokenCount();
  };

  // features/variable-actions.js
  const collectRows = (value, path, schemaNode, rows) => {
    if (rejectUnsafeSegment(path.at(-1))) return;
    const logical = logicalValue(value, schemaNode);
    const description = descriptionOf(value, schemaNode);
    const shouldDescend = isPlainObject(logical) && Object.keys(logical).filter(key => key !== '$meta' && key !== '$internal').length > 0;
    if (shouldDescend) {
      for (const [key, child] of Object.entries(logical)) {
        if (key === '$meta' || key === '$internal') continue;
        collectRows(child, [...path, ...(logical !== value ? [0] : []), key], schemaChild(schemaNode, key), rows);
      }
      return;
    }
    rows.push({ path, schemaNode, value, logical, description });
  };

  const allGroups = () => {
    if (!isPlainObject(state.draft?.stat_data)) return [];
    const rootSchema = state.draft.schema;
    return Object.entries(state.draft.stat_data)
      .filter(([key]) => !rejectUnsafeSegment(key))
      .map(([key, value]) => {
        const rows = [];
        collectRows(value, [key], schemaChild(rootSchema, key), rows);
        return { key, rows };
      });
  };

  const countLeaves = data => {
    if (!isPlainObject(data?.stat_data)) return 0;
    return Object.entries(data.stat_data).reduce((count, [key, value]) => {
      const rows = [];
      collectRows(value, [key], schemaChild(data.schema, key), rows);
      return count + rows.length;
    }, 0);
  };

  const typeLabel = value => {
    if (typeof value === 'boolean') return 'Công tắc';
    if (typeof value === 'number') return 'Số';
    if (typeof value === 'string') return 'Văn bản';
    if (Array.isArray(value)) return 'Mảng · JSON';
    if (isPlainObject(value)) return 'Đối tượng · JSON';
    if (value === null) return 'Giá trị rỗng · JSON';
    return 'Giá trị phức hợp · JSON';
  };

  const updateDirtyState = () => {
    try {
      state.dirty = Boolean(state.fieldErrors.size || (state.draft && stableStringify(state.draft) !== state.sourceFingerprint));
    } catch (error) {
      state.fieldErrors.set('__root__', error.message);
      state.dirty = true;
    }
    if (state.fieldErrors.size > 0) setStatus(`Có ${state.fieldErrors.size} mục nhập cần sửa đổi`, 'error');
    else if (state.conflict) setStatus('Dữ liệu bên ngoài đã thay đổi, vui lòng tải lại phiên bản mới nhất', 'warning');
    else if (state.dirty) setStatus('Có thay đổi chưa được lưu', 'warning');
    else setStatus(state.draft ? 'Đã đồng bộ với phản hồi hiện tại' : state.status, state.draft ? 'success' : state.statusTone);
    updateControls();
  };

  const beginEdit = label => {
    if (!state.draft || !state.context || state.activeEdit) return;
    state.activeEdit = { label: String(label || 'Chỉnh sửa biến'), before: clone(state.draft.stat_data), changed: false };
  };

  const markEditChanged = () => {
    if (state.activeEdit) state.activeEdit.changed = true;
  };

  const finishEdit = () => {
    const edit = state.activeEdit;
    state.activeEdit = null;
    if (!edit?.changed || !state.draft || !state.context) return;
    const after = clone(state.draft.stat_data);
    if (stableStringify(edit.before) === stableStringify(after)) return;
    state.editHistory.push({
      contextKey: state.context.key,
      label: edit.label,
      before: edit.before,
      afterFingerprint: stableStringify(after),
      at: new Date().toISOString(),
    });
    persistEditHistory();
    updateControls();
  };

  const withEdit = (label, callback) => {
    beginEdit(label);
    try {
      const result = callback();
      markEditChanged();
      finishEdit();
      return result;
    } catch (error) {
      state.activeEdit = null;
      throw error;
    }
  };

  const bindEditInput = (input, label) => {
    input.addEventListener('focus', () => beginEdit(label));
    input.addEventListener('blur', finishEdit);
    return input;
  };

  const nextCopyName = (parent, sourceName) => {
    const base = `${String(sourceName)}-copy`;
    if (!Object.prototype.hasOwnProperty.call(parent, base)) return base;
    let index = 2;
    while (Object.prototype.hasOwnProperty.call(parent, `${base}-${index}`)) index += 1;
    return `${base}-${index}`;
  };

  const nextBlankName = parent => {
    const base = 'Mục mới';
    if (!Object.prototype.hasOwnProperty.call(parent, base)) return base;
    let index = 2;
    while (Object.prototype.hasOwnProperty.call(parent, `${base}-${index}`)) index += 1;
    return `${base}-${index}`;
  };

  const blankLike = (value) => {
    if (isValueWithDescription(value)) return [blankLike(value[0]), value[1]];
    if (Array.isArray(value)) return [];
    if (isPlainObject(value)) {
      return Object.fromEntries(Object.entries(value).map(([key, child]) => {
        if (key === '$meta' || key === '$internal') return [key, clone(child)];
        return [key, blankLike(child)];
      }));
    }
    if (typeof value === 'string') return '';
    if (typeof value === 'number') return 0;
    if (typeof value === 'boolean') return false;
    return null;
  };

  const cloneSiblingAtPath = (rootValue, path) => {
    if (!Array.isArray(path) || path.length < 1 || path.some(segment => rejectUnsafeSegment(segment))) throw new Error('Node này không thể làm nguồn thêm mới');
    const parent = valueAt(rootValue, path.slice(0, -1));
    const key = path.at(-1);
    if (!isPlainObject(parent) || !Object.prototype.hasOwnProperty.call(parent, key)) throw new Error('Chỉ có thể thêm mục cùng cấp cạnh mục đối tượng');
    const newKey = nextCopyName(parent, key);
    parent[newKey] = clone(parent[key]);
    return { key: newKey, path: [...path.slice(0, -1), newKey] };
  };

  const addBlankSiblingAtPath = (rootValue, path) => {
    if (!Array.isArray(path) || path.length < 1 || path.some(segment => rejectUnsafeSegment(segment))) throw new Error('Node này không thể làm nguồn thêm mới');
    const parent = valueAt(rootValue, path.slice(0, -1));
    const key = path.at(-1);
    if (!isPlainObject(parent) || !Object.prototype.hasOwnProperty.call(parent, key)) throw new Error('Chỉ có thể thêm mục cùng cấp cạnh mục đối tượng');
    const newKey = nextBlankName(parent);
    parent[newKey] = blankLike(parent[key]);
    return { key: newKey, path: [...path.slice(0, -1), newKey] };
  };

  const removeSiblingAtPath = (rootValue, path) => {
    if (!Array.isArray(path) || path.length < 1 || path.some(segment => rejectUnsafeSegment(segment))) throw new Error('Node này không thể xóa');
    const parent = valueAt(rootValue, path.slice(0, -1));
    const key = path.at(-1);
    if (!isPlainObject(parent) || !Object.prototype.hasOwnProperty.call(parent, key)) throw new Error('Mục không còn tồn tại');
    delete parent[key];
    const keyStr = pathKey(path);
    for (const errorKey of state.fieldErrors.keys()) {
      if (errorKey === keyStr || errorKey.startsWith(keyStr.slice(0, -1))) {
        state.fieldErrors.delete(errorKey);
      }
    }
    return { key, parentPath: path.slice(0, -1) };
  };

  const scrollPathIntoView = (targetPath, { selectName = true } = {}) => {
    if (!Array.isArray(targetPath) || !targetPath.length) return;
    for (let i = 1; i <= targetPath.length; i++) {
      const subPath = targetPath.slice(0, i);
      if (subPath.length === 1) {
        state.expanded.add(subPath[0]);
      } else {
        state.expanded.add(`node:${pathKey(subPath)}`);
      }
    }
    renderBody();

    const targetKey = pathKey(targetPath);
    const schedule = hostWindow.requestAnimationFrame || (cb => hostWindow.setTimeout(cb, 40));
    schedule(() => {
      const all = typeof body.querySelectorAll === 'function'
        ? Array.from(body.querySelectorAll('[data-path-key]'))
        : [];
      const targetEl = all.find(el => el.dataset?.pathKey === targetKey);
      if (!targetEl) return;

      if (typeof targetEl.scrollIntoView === 'function') {
        targetEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }

      if (targetEl.classList) {
        targetEl.classList.remove('fy-highlight-new');
        void targetEl.offsetWidth;
        targetEl.classList.add('fy-highlight-new');
        hostWindow.setTimeout?.(() => {
          targetEl.classList?.remove('fy-highlight-new');
        }, 2200);
      }

      if (selectName) {
        const nameInput = targetEl.querySelector?.('.fy-node-name-input');
        if (nameInput && typeof nameInput.focus === 'function') {
          hostWindow.setTimeout?.(() => {
            nameInput.focus();
            nameInput.select?.();
          }, 80);
        }
      }
    });
  };

  const renameSiblingAtPath = (rootValue, path, requestedName) => {
    if (!Array.isArray(path) || path.length < 1 || path.some(segment => rejectUnsafeSegment(segment))) throw new Error('Node này không thể đổi tên');
    const parent = valueAt(rootValue, path.slice(0, -1));
    const oldKey = path.at(-1);
    const newKey = String(requestedName ?? '').trim();
    if (!isPlainObject(parent) || !Object.prototype.hasOwnProperty.call(parent, oldKey)) throw new Error('Mục không còn tồn tại');
    if (!newKey || rejectUnsafeSegment(newKey)) throw new Error('Tên mới trống hoặc thuộc tên được bảo vệ');
    if (newKey !== oldKey && Object.prototype.hasOwnProperty.call(parent, newKey)) throw new Error(`Cùng cấp đã tồn tại "${newKey}"`);
    if (newKey === oldKey) return { key: oldKey, path };
    const entries = Object.entries(parent).map(([key, value]) => [key === oldKey ? newKey : key, value]);
    for (const key of Object.keys(parent)) delete parent[key];
    for (const [key, value] of entries) parent[key] = value;
    return { key: newKey, path: [...path.slice(0, -1), newKey] };
  };

  // features/variables.js
  const renderNameInput = (label, path) => {
    const display = h('span', { className: 'fy-node-name-text', text: label });
    const button = h('button', { className: 'fy-node-rename', type: 'button', text: 'Đổi tên', 'aria-label': `Sửa tiêu đề ${label}`, title: `Sửa tiêu đề của "${label}"` });
    const input = h('input', { className: 'fy-node-name-input', type: 'text', value: label, 'aria-label': `Tên mục ${label}`, hidden: true });
    input.value = label;
    let committed = label;
    let editing = false;
    const stop = event => { event.preventDefault?.(); event.stopPropagation?.(); };
    button.addEventListener('click', event => {
      stop(event);
      display.hidden = true; button.hidden = true; input.hidden = false; editing = true;
      input.focus(); input.select();
    });
    const commitName = () => {
      if (!editing) return;
      editing = false;
      display.hidden = false; button.hidden = false; input.hidden = true;
      const requested = input.value.trim();
      if (!requested || requested === committed) {
        input.value = committed;
        return;
      }
      try {
        const renamed = withEdit(`Đổi tên "${label}"`, () => renameSiblingAtPath(state.draft.stat_data, path, requested));
        committed = renamed.key;
        updateDirtyState();
        renderBody();
        notify(`Đã đổi tên thành "${renamed.key}"`, 'success');
      } catch (error) {
        input.value = committed;
        notify(error.message, 'error');
      }
    };
    input.addEventListener('click', stop);
    input.addEventListener('pointerdown', event => event.stopPropagation?.());
    input.addEventListener('keydown', event => {
      if (event.key === 'Enter') { event.preventDefault(); input.blur(); }
      if (event.key === 'Escape') { input.value = committed; input.blur(); }
    });
    input.addEventListener('change', commitName);
    input.addEventListener('blur', commitName);
    return h('span', { className: 'fy-node-name-control' }, [display, button, input]);
  };

  const renderField = (row, flatText = false) => {
    const key = pathKey(row.path);
    const value = logicalValue(valueAt(state.draft.stat_data, row.path), row.schemaNode);
    const label = String(row.path.at(-1));
    const breadcrumb = row.path.length > 1 ? row.path.slice(0, -1).filter(key => key !== 0).join(' › ') : 'Gốc nhóm';
    const field = h('div', { className: 'fy-field', dataset: { pathKey: key } });
    const error = h('div', { className: 'fy-field-error', role: 'alert' });
    const head = h('div', { className: 'fy-field-head' }, [
      h('div', { className: 'fy-field-label' }, [renderNameInput(label, row.path), h('div', { className: 'fy-path', text: breadcrumb })]),
      h('span', { className: 'fy-type', text: typeLabel(value) }),
    ]);
    const parentValue = row.path.length > 1 ? valueAt(state.draft.stat_data, row.path.slice(0, -1)) : null;
    if (isPlainObject(parentValue) && typeof row.path.at(-1) !== 'number' && !rejectUnsafeSegment(row.path.at(-1))) {
      const addSibling = h('button', { className: 'fy-mini', type: 'button', text: '＋ Thêm', title: `Thêm mục trống cùng cấp theo cấu trúc thuộc tính của "${label}"` });
      addSibling.addEventListener('click', () => {
        try {
          const added = withEdit(`Thêm mục cùng cấp cho "${label}"`, () => addBlankSiblingAtPath(state.draft.stat_data, row.path));
          updateDirtyState();
          state.context.leafCount = countLeaves(state.draft);
          subtitle.textContent = describeContext(state.context);
          notify(`Đã thêm mục trống cùng cấp "${added.key}", vui lòng điền trực tiếp`, 'success');
          scrollPathIntoView(added.path, { selectName: true });
        } catch (issue) { notify(issue.message, 'error'); }
      });
      const cloneButton = h('button', { className: 'fy-mini', type: 'button', text: 'Nhân bản', title: `Nhân bản hoàn chỉnh "${label}"` });
      cloneButton.addEventListener('click', () => {
        try {
          const cloned = withEdit(`Nhân bản "${label}"`, () => cloneSiblingAtPath(state.draft.stat_data, row.path));
          updateDirtyState();
          state.context.leafCount = countLeaves(state.draft);
          subtitle.textContent = describeContext(state.context);
          notify(`Đã nhân bản mục cùng cấp "${cloned.key}"`, 'success');
          scrollPathIntoView(cloned.path, { selectName: true });
        } catch (issue) { notify(issue.message, 'error'); }
      });
      const deleteButton = h('button', { className: 'fy-mini fy-mini-danger', type: 'button', text: 'Xóa', title: `Xóa mục "${label}"` });
      deleteButton.addEventListener('click', () => {
        if (!hostWindow.confirm?.(`Bạn có chắc chắn muốn xóa mục "${label}" không?`)) return;
        try {
          withEdit(`Xóa "${label}"`, () => removeSiblingAtPath(state.draft.stat_data, row.path));
          updateDirtyState();
          state.context.leafCount = countLeaves(state.draft);
          subtitle.textContent = describeContext(state.context);
          notify(`Đã xóa mục "${label}"`, 'info');
          renderBody();
        } catch (issue) { notify(issue.message, 'error'); }
      });
      head.append(h('span', { className: 'fy-node-actions' }, [addSibling, cloneButton, deleteButton]));
    }
    field.append(head);
    if (row.description) field.append(h('div', { className: 'fy-description', text: row.description }));

    const commit = nextValue => {
      if (!state.activeEdit) beginEdit(`Sửa "${label}"`);
      setLogicalValueAt(state.draft.stat_data, row.path, nextValue, row.schemaNode);
      markEditChanged();
      state.fieldErrors.delete(key);
      error.textContent = '';
      updateDirtyState();
    };

    if (typeof value === 'boolean') {
      const input = h('input', { type: 'checkbox', 'aria-label': label });
      input.checked = value;
      input.addEventListener('change', () => {
        text.textContent = input.checked ? 'Bật' : 'Tắt';
        withEdit(`Sửa "${label}"`, () => commit(input.checked));
      });
      const text = h('span', { text: value ? 'Bật' : 'Tắt' });
      field.append(h('label', { className: 'fy-toggle' }, [text, input]));
    } else if (typeof value === 'number') {
      const input = h('input', { className: 'fy-input', type: 'number', step: 'any', value: String(value), 'aria-label': label });
      input.addEventListener('input', () => {
        const raw = input.value.trim();
        const parsed = Number(raw);
        if (!raw || !Number.isFinite(parsed)) {
          state.fieldErrors.set(key, 'Vui lòng nhập số hợp lệ');
          error.textContent = 'Vui lòng nhập số hợp lệ';
          updateDirtyState();
          return;
        }
        commit(parsed);
      });
      field.append(bindEditInput(input, `Sửa "${label}"`));
    } else if (typeof value === 'string') {
      const input = flatText || value.length > 80 || value.includes('\n')
        ? h('textarea', { className: 'fy-textarea', 'aria-label': label })
        : h('input', { className: 'fy-input', type: 'text', 'aria-label': label });
      input.value = value;
      input.addEventListener('input', () => commit(input.value));
      field.append(bindEditInput(input, `Sửa "${label}"`));
    } else {
      const currentRaw = state.rawComplexValues.get(key) ?? JSON.stringify(value, null, 2);
      const input = h('textarea', { className: 'fy-textarea', dataset: { json: 'true' }, spellcheck: 'false', 'aria-label': `${label} JSON` });
      input.value = currentRaw;
      input.addEventListener('input', () => {
        state.rawComplexValues.set(key, input.value);
        try {
          const parsed = JSON.parse(input.value);
          if (Array.isArray(value) && !Array.isArray(parsed)) throw new Error('Kiểu dữ liệu không khớp');
          if (isPlainObject(value) && !isPlainObject(parsed)) throw new Error('Kiểu dữ liệu không khớp');
          const preserveMetadata = (oldValue, newValue) => {
            if (!oldValue || typeof oldValue !== 'object') return;
            for (const [name, child] of Object.entries(oldValue)) {
              if (name === '$meta' || name === '$internal') {
                if (stableStringify(child) !== stableStringify(newValue?.[name])) throw new Error('Không thể thay đổi siêu dữ liệu');
              } else preserveMetadata(child, newValue?.[name]);
            }
          };
          preserveMetadata(value, parsed);
          commit(parsed);
        } catch (issue) {
          state.fieldErrors.set(key, 'Định dạng JSON, kiểu dữ liệu hoặc metadata không đúng');
          error.textContent = `Định dạng JSON, kiểu dữ liệu hoặc metadata không đúng; chỉ có thể lưu sau khi sửa (${issue.message})`;
          updateDirtyState();
        }
      });
      field.append(bindEditInput(input, `Sửa "${label}"`));
    }
    field.append(error);
    return field;
  };

  const rowMatchesQuery = (row, query) => {
    if (!query) return true;
    const haystack = [row.path.filter(key => key !== 0).join(' '), row.description, escapeSearchValue(logicalValue(valueAt(state.draft.stat_data, row.path), row.schemaNode))]
      .join(' ')
      .toLocaleLowerCase('zh-CN');
    return haystack.includes(query);
  };

  const renderTreeContents = (rawValue, path, schemaNode, query = '') => {
    const logical = logicalValue(rawValue, schemaNode);
    if (!isPlainObject(logical)) return [renderField({ path, schemaNode, value: rawValue, logical, description: descriptionOf(rawValue, schemaNode) })];
    const wrapper = logical !== rawValue ? [0] : [];
    const nodes = [];
    for (const [childKey, childRaw] of Object.entries(logical)) {
      if (rejectUnsafeSegment(childKey)) continue;
      const childPath = [...path, ...wrapper, childKey];
      const childSchema = schemaChild(schemaNode, childKey);
      const childLogical = logicalValue(childRaw, childSchema);
      const childRows = [];
      collectRows(childRaw, childPath, childSchema, childRows);
      const titleMatches = [childKey, childPath.filter(key => key !== 0).join(' ')].join(' ').toLocaleLowerCase('zh-CN').includes(query);
      if (query && !titleMatches && !childRows.some(row => rowMatchesQuery(row, query))) continue;
      if (!isPlainObject(childLogical)) {
        nodes.push(renderField({ path: childPath, schemaNode: childSchema, value: childRaw, logical: childLogical, description: descriptionOf(childRaw, childSchema) }));
        continue;
      }

      const nodeKey = `node:${pathKey(childPath)}`;
      const details = h('details', { className: 'fy-node', dataset: { pathKey: pathKey(childPath) } });
      details.open = Boolean(query || state.expanded.has(nodeKey) || childPath.filter(key => key !== 0).length <= 2);
      details.addEventListener('toggle', () => {
        if (details.open) state.expanded.add(nodeKey);
        else state.expanded.delete(nodeKey);
      });
      const addSibling = h('button', { className: 'fy-mini', type: 'button', text: '＋ Thêm', title: `Thêm mục trống cùng cấp theo cấu trúc thuộc tính của "${childKey}"` });
      addSibling.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        try {
          const added = withEdit(`Thêm mục cùng cấp cho "${childKey}"`, () => addBlankSiblingAtPath(state.draft.stat_data, childPath));
          updateDirtyState();
          state.context.leafCount = countLeaves(state.draft);
          subtitle.textContent = describeContext(state.context);
          notify(`Đã thêm mục trống cùng cấp "${added.key}", bây giờ có thể điền trực tiếp`, 'success');
          scrollPathIntoView(added.path, { selectName: true });
        } catch (error) { notify(error.message, 'error'); }
      });
      const cloneButton = h('button', { className: 'fy-mini', type: 'button', text: 'Nhân bản', title: `Nhân bản hoàn chỉnh "${childKey}"` });
      cloneButton.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        try {
          const cloned = withEdit(`Nhân bản "${childKey}"`, () => cloneSiblingAtPath(state.draft.stat_data, childPath));
          updateDirtyState();
          state.context.leafCount = countLeaves(state.draft);
          subtitle.textContent = describeContext(state.context);
          notify(`Đã nhân bản mục cùng cấp "${cloned.key}"`, 'success');
          scrollPathIntoView(cloned.path, { selectName: true });
        } catch (error) { notify(error.message, 'error'); }
      });
      const deleteButton = h('button', { className: 'fy-mini fy-mini-danger', type: 'button', text: 'Xóa', title: `Xóa "${childKey}" cùng tất cả các mục con` });
      deleteButton.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        if (!hostWindow.confirm?.(`Bạn có chắc chắn muốn xóa "${childKey}" cùng tất cả các mục con không?`)) return;
        try {
          withEdit(`Xóa "${childKey}"`, () => removeSiblingAtPath(state.draft.stat_data, childPath));
          updateDirtyState();
          state.context.leafCount = countLeaves(state.draft);
          subtitle.textContent = describeContext(state.context);
          notify(`Đã xóa "${childKey}"`, 'info');
          renderBody();
        } catch (error) { notify(error.message, 'error'); }
      });
      const summary = h('summary', {}, [
        h('span', { className: 'fy-chevron', text: '›', 'aria-hidden': 'true' }),
