      details.append(summary, h('div', { className: 'fy-node-content' }, children.length ? children : [h('div', { className: 'fy-help', text: 'Đối tượng rỗng; có thể dùng "Thêm cùng cấp" để sao chép cấu trúc giữ chỗ này.' })]));
      nodes.push(details);
    }
    return nodes;
  };

  const renderVariablesBody = () => {
    body.replaceChildren();
    if (state.loading) {
      body.append(h('div', { className: 'fy-empty' }, [
        h('div', { className: 'fy-empty-icon', text: '✦' }),
        h('strong', { text: 'Đang đọc trình sửa đổi…' }),
        h('p', { text: 'Đang chờ giao diện MVU và định vị phản hồi hiện tại.' }),
      ]));
      return;
    }
    if (!state.draft) {
      body.append(h('div', { className: 'fy-empty' }, [
        h('div', { className: 'fy-empty-icon', text: '◇' }),
        h('strong', { text: state.apiTimedOut ? 'Không phát hiện MVU' : 'Phản hồi hiện tại không có dữ liệu MVU khả dụng' }),
        h('p', { text: state.apiTimedOut ? 'Vui lòng chuyển sang thẻ nhân vật hoặc cuộc trò chuyện đã kích hoạt MVU; trình sửa đổi sẽ không tự tạo biến cho thẻ không có MVU.' : 'Sau khi tạo hoặc chuyển sang phản hồi chứa biến MVU, hãy nhấp vào nút làm mới ở góc trên bên phải.' }),
      ]));
      return;
    }

    const shapeIssues = inspectEntryShape(state.draft.stat_data, state.draft.schema, state.source?.stat_data);
    const shapeCard = h('details', { className: 'fy-group fy-shape-check' });
    shapeCard.append(h('summary', {}, [h('span', { className: 'fy-chevron', text: '›' }), h('span', { className: 'fy-group-name', text: 'Kiểm tra cấu trúc mục mới' }), h('span', { className: 'fy-count', text: shapeIssues.length ? `${shapeIssues.length} mục cần kiểm tra` : 'Cấu trúc bình thường' })]));
    const shapeContent = h('div', { className: 'fy-group-content' });
    shapeContent.append(h('p', { className: 'fy-help', text: 'Kiểm tra các mục thiếu và kiểu trường dựa trên schema của thẻ và các mục cùng nhóm. So sánh cùng nhóm chỉ là gợi ý, việc có cần trường đó hay không vui lòng dựa trên thiết lập của thẻ.' }));
    for (const issue of shapeIssues.slice(0, 30)) {
      const row = h('div', { className: 'fy-shape-row' }, [h('span', { text: `${issue.path.length ? issue.path.join(' › ') + ': ' : ''}${issue.message}` })]);
      if (issue.kind === 'missing') {
        const fill = h('button', { className: 'fy-mini', type: 'button', text: 'Bổ sung trường trống' });
        fill.addEventListener('click', () => {
          const sibling = valueAt(state.draft.stat_data, issue.path.slice(0, -2));
          const reference = Object.values(sibling).find(candidate => isPlainObject(candidate) && Object.prototype.hasOwnProperty.call(candidate, issue.path.at(-1)));
          if (!reference) return;
          withEdit(`Bổ sung đầy đủ ${issue.path.join(' › ')}`, () => { valueAt(state.draft.stat_data, issue.path.slice(0, -1))[issue.path.at(-1)] = blankLike(reference[issue.path.at(-1)]); });
          updateDirtyState(); renderBody();
        });
        row.append(fill);
      }
      shapeContent.append(row);
    }
    if (shapeIssues.length > 30) shapeContent.append(h('p', { className: 'fy-help', text: `Còn ${shapeIssues.length - 30} mục nữa, vui lòng xử lý danh sách hiện tại trước.` }));
    shapeCard.append(shapeContent);
    body.append(shapeCard);

    const query = state.query.trim().toLocaleLowerCase('zh-CN');
    let visibleCount = 0;
    for (const group of allGroups()) {
      if (!query && trainerGroupFocus !== null && group.key !== trainerGroupFocus) continue;
      const groupMatches = group.key.toLocaleLowerCase('zh-CN').includes(query);
      const rows = query
        ? group.rows.filter(row => groupMatches || rowMatchesQuery(row, query))
        : group.rows;
      if (!rows.length) continue;
      visibleCount += rows.length;
      const groupPath = [group.key];
      const details = h('details', { className: 'fy-group', dataset: { pathKey: pathKey(groupPath) } });
      details.open = query ? true : state.expanded.has(group.key);
      details.addEventListener('toggle', () => {
        if (details.open) state.expanded.add(group.key);
        else state.expanded.delete(group.key);
      });
      const addGroup = h('button', { className: 'fy-mini', type: 'button', text: '＋ Thêm', title: `Thêm nhóm trống "${group.key}"` });
      addGroup.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        try {
          const added = withEdit(`Thêm nhóm cùng cấp "${group.key}"`, () => addBlankSiblingAtPath(state.draft.stat_data, groupPath));
          updateDirtyState();
          state.context.leafCount = countLeaves(state.draft);
          subtitle.textContent = describeContext(state.context);
          notify(`Đã thêm nhóm trống "${added.key}"`, 'success');
          scrollPathIntoView(added.path, { selectName: true });
        } catch (error) { notify(error.message, 'error'); }
      });
      const cloneGroup = h('button', { className: 'fy-mini', type: 'button', text: 'Nhân bản', title: `Nhân bản hoàn chỉnh nhóm "${group.key}"` });
      cloneGroup.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        try {
          const cloned = withEdit(`Nhân bản nhóm "${group.key}"`, () => cloneSiblingAtPath(state.draft.stat_data, groupPath));
          updateDirtyState();
          state.context.leafCount = countLeaves(state.draft);
          subtitle.textContent = describeContext(state.context);
          notify(`Đã nhân bản nhóm "${cloned.key}"`, 'success');
          scrollPathIntoView(cloned.path, { selectName: true });
        } catch (error) { notify(error.message, 'error'); }
      });
      const deleteGroup = h('button', { className: 'fy-mini fy-mini-danger', type: 'button', text: 'Xóa', title: `Xóa nhóm "${group.key}" cùng toàn bộ dữ liệu` });
      deleteGroup.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        if (!hostWindow.confirm?.(`Bạn có chắc chắn muốn xóa nhóm "${group.key}" cùng toàn bộ dữ liệu không?`)) return;
        try {
          withEdit(`Xóa nhóm "${group.key}"`, () => removeSiblingAtPath(state.draft.stat_data, groupPath));
          updateDirtyState();
          state.context.leafCount = countLeaves(state.draft);
          subtitle.textContent = describeContext(state.context);
          notify(`Đã xóa nhóm "${group.key}"`, 'info');
          renderBody();
        } catch (error) { notify(error.message, 'error'); }
      });
      details.append(
        h('summary', {}, [
          h('span', { className: 'fy-chevron', text: '›', 'aria-hidden': 'true' }),
          renderNameInput(group.key, groupPath),
          h('span', { className: 'fy-count', text: String(rows.length) }),
          h('span', { className: 'fy-node-actions' }, [addGroup, cloneGroup, deleteGroup]),
        ]),
        h('div', { className: 'fy-group-content' }, renderTreeContents(state.draft.stat_data[group.key], [group.key], schemaChild(state.draft.schema, group.key), groupMatches ? '' : query)),
      );
      body.append(details);
    }
    if (!visibleCount) {
      body.append(h('div', { className: 'fy-empty' }, [
        h('div', { className: 'fy-empty-icon', text: '⌕' }),
        h('strong', { text: 'Không có biến phù hợp' }),
        h('p', { text: 'Hãy thử từ khóa khác; tìm kiếm sẽ đồng thời kiểm tra tên, đường dẫn, mô tả và giá trị.' }),
      ]));
    }
  };

  // +trainer-locks.js
  const trainerLockKey = scope => STORAGE_PREFIX + ':field-locks:' + scope;
  const validTrainerLockPath = path => Array.isArray(path) && path.length > 0 && path.length <= 64
    && path.every(key => (typeof key === 'string' && key.length <= 512 || Number.isSafeInteger(key) && key >= 0) && !rejectUnsafeSegment(key));
  const readTrainerLocks = (scope = trainerPromptScope()) => {
    if (!scope) return new Map();
    const data = readStorage(trainerLockKey(scope), null);
    return new Map((data?.version === 1 && Array.isArray(data.fields) ? data.fields.slice(0, 512) : [])
      .filter(entry => validTrainerLockPath(entry?.path) && [1, 2].includes(entry.level))
      .map(entry => [pathKey(entry.path), entry]));
  };
  const trainerPathPrefix = (prefix, path) => prefix.length <= path.length
    && prefix.every((key, index) => String(key) === String(path[index]));
  const trainerAiLockReason = operation => {
    const path = operation?.path;
    if (!Array.isArray(path)) return '';
    const parentPath = path.slice(0, -1);
    const changesArrayIndices = operation.op !== 'replace' && Array.isArray(valueAt(state.draft?.stat_data, parentPath));
    for (const { path: locked, level } of readTrainerLocks().values()) {
      if (level !== 2) continue;
      const shifts = changesArrayIndices && locked.length > parentPath.length && trainerPathPrefix(parentPath, locked)
        && Number(path.at(-1)) <= Number(locked[parentPath.length]);
      if (shifts || trainerPathPrefix(path, locked) || trainerPathPrefix(locked, path)) return 'Biến này đã được gia cố, AI không thể sửa đổi.';
    }
    return '';
  };
  const trainerOwn = (node, key) => node !== null && typeof node === 'object' && Object.hasOwn(node, key);
  const assertTrainerStrongLocks = working => {
    for (const { path, level } of readTrainerLocks().values()) {
      if (level === 2 && stableStringify(valueAt(working, path)) !== stableStringify(valueAt(state.draft.stat_data, path))) {
        throw new Error('Đề xuất sẽ gián tiếp thay đổi biến đã gia cố, chưa áp dụng.');
      }
    }
  };
  const trainerContainer = value => Array.isArray(value) ? 'array' : isPlainObject(value) ? 'object' : '';
  // Restore only the affected path. If a command removed its parent, restore
  // the smallest missing/retyped container from MVU's own pre-update snapshot.
  const restoreTrainerLock = (next, old, path, offset = 0) => {
    const key = path[offset], had = trainerOwn(old, key), has = trainerOwn(next, key);
    const prefix = path.slice(0, offset + 1);
    if (!had) {
      if (!has) return null;
      if (Array.isArray(next)) return null;
      delete next[key];
      return prefix;
    }
    const last = offset === path.length - 1, oldType = trainerContainer(old[key]);
    if (!last && has && oldType && oldType === trainerContainer(next[key])) {
      if (oldType === 'array' && next[key].length !== old[key].length) { next[key] = clone(old[key]); return prefix; }
      return restoreTrainerLock(next[key], old[key], path, offset + 1);
    }
    if (has && stableStringify(next[key]) === stableStringify(old[key])) return null;
    next[key] = clone(old[key]);
    return prefix;
  };
  const stripTrainerDelta = (delta, path) => {
    const parent = valueAt(delta, path.slice(0, -1)), key = path.at(-1);
    if (trainerOwn(parent, key) && !Array.isArray(parent)) delete parent[key];
  };
  const trainerMvuUpdates = new WeakMap();
  const startTrainerMvuUpdate = next => {
    const scope = trainerPromptScope();
    if (!state.destroyed && scope && isPlainObject(next?.stat_data)) trainerMvuUpdates.set(next, { scope });
  };
  const guardTrainerMvuUpdate = (next, before) => {
    const update = next && trainerMvuUpdates.get(next);
    if (state.destroyed || !update || update.scope !== trainerPromptScope()
      || !isPlainObject(before?.stat_data) || !isPlainObject(next.stat_data)) return;
    const locks = readTrainerLocks(update.scope);
    if (!locks.size) return;
    update.before = before;
    for (const { path } of locks.values()) {
      try {
        const changed = restoreTrainerLock(next.stat_data, before.stat_data, path);
        if (!changed) continue;
        if (isPlainObject(next.display_data)) restoreTrainerLock(next.display_data, before.stat_data, changed);
        stripTrainerDelta(next.delta_data, changed);
      } catch { /* A malformed branch must not interrupt the host generation. */ }
    }
  };
  const beforeTrainerMvuWrite = context => {
    const next = context?.variables, update = next && trainerMvuUpdates.get(next);
    if (update?.before) guardTrainerMvuUpdate(next, update.before);
    if (update) trainerMvuUpdates.delete(next);
  };
  const trainerLockButton = (row, locks) => {
    const key = pathKey(row.path), scope = trainerPromptScope(), contextKey = state.context?.key;
    const button = h('button', { type: 'button', className: 'fy-field-lock', disabled: scope && validTrainerLockPath(row.path) ? null : true });
    const paint = level => {
      button.dataset.lockLevel = String(level);
      const label = ['Chưa khóa: Nhấp để khóa cập nhật MVU', 'Đã khóa: Nhấp để gia cố, ngăn AI sửa đổi', 'Đã gia cố: Nhấp để mở khóa'][level];
      button.setAttribute('aria-label', label + ' · ' + row.path.join(' › '));
      button.title = label;
      button.replaceChildren(h('svg', { viewBox: '0 0 20 20', width: 16, height: 16, fill: 'none', 'aria-hidden': 'true' }, [
        h('rect', { x: 4, y: 8, width: 12, height: 9, rx: 2, stroke: 'currentColor', 'stroke-width': 1.5 }),
        h('path', { d: level ? 'M6 8V6a4 4 0 0 1 8 0v2' : 'M6 8V6a4 4 0 0 1 8 0', stroke: 'currentColor', 'stroke-width': 1.5 }),
        h('path', { d: level === 2 ? 'M7.5 12.5l1.5 1.5 3.5-3.5' : 'M10 11v3', stroke: 'currentColor', 'stroke-width': 1.5 }),
      ]));
    };
    paint(locks.get(key)?.level ?? 0);
    button.addEventListener('click', () => {
      if (state.destroyed || state.loading || state.saving || !trainerTargetCurrent()
        || state.context?.key !== contextKey || trainerPromptScope() !== scope) return;
      const latest = readTrainerLocks(scope), level = ((latest.get(key)?.level ?? 0) + 1) % 3;
      if (level) {
        if (!latest.has(key) && latest.size >= 512) return notify('Khóa biến của cuộc trò chuyện này đã đạt giới hạn tối đa.', 'warning');
        latest.set(key, { path: row.path, level });
      } else latest.delete(key);
      if (!writeStorage(trainerLockKey(scope), { version: 1, fields: [...latest.values()] })) return notify('Khóa biến chưa được lưu.', 'warning');
      paint(level);
    });
    return button;
  };

  // +trainer-options.js
  let trainerOptionLimit = 120;
  let trainerExpandedValue = null;
  const collapseTrainerValue = (blur = false) => {
    if (!trainerExpandedValue) return false;
    const { slot, editor } = trainerExpandedValue;
    trainerExpandedValue = null;
    delete slot.dataset.expanded;
    if (blur) editor.blur();
    return true;
  };
  const trainerValueCell = editor => {
    const slot = h('div', { className: 'fy-option-value' }, [editor]);
    if (editor?.tagName !== 'TEXTAREA') return slot;
    editor.rows = 1;
    editor.addEventListener('click', () => {
      if (trainerExpandedValue?.editor === editor || !editor.value
        || editor.scrollWidth <= editor.clientWidth + 2 && editor.scrollHeight <= editor.clientHeight + 2) return;
      collapseTrainerValue();
      const bounds = body.getBoundingClientRect(), anchor = slot.getBoundingClientRect();
      const width = Math.max(anchor.width, Math.min(560, bounds.width - 24));
      const left = clamp(anchor.left, bounds.left + 4, bounds.right - width - 20);
      const maximumHeight = Math.max(44, Math.min(240, bounds.height - 12));
      slot.style.setProperty('--trainer-value-width', width + 'px');
      slot.style.setProperty('--trainer-value-left', (left - anchor.left) + 'px');
      slot.style.setProperty('--trainer-value-top', '0px');
      slot.style.setProperty('--trainer-value-height', '44px');
      slot.dataset.expanded = 'true';
      trainerExpandedValue = { slot, editor };
      const height = Math.min(maximumHeight, Math.max(44, editor.scrollHeight + 2));
      slot.style.setProperty('--trainer-value-height', height + 'px');
      slot.style.setProperty('--trainer-value-top', (clamp(anchor.top, bounds.top + 2, bounds.bottom - height - 2) - anchor.top) + 'px');
    });
    editor.addEventListener('blur', () => { if (trainerExpandedValue?.editor === editor) collapseTrainerValue(); });
    return slot;
  };
  const renderTrainerOption = ({ row }, locks) => {
    // Reuse the MVU field's type-specific bindings, validation and draft transactions.
    const field = renderField(row, true);
    const editor = field.querySelector(':scope > .fy-input, :scope > .fy-textarea, :scope > .fy-toggle');
    const error = field.querySelector('.fy-field-error');
    const label = String(row.path.at(-1));
    const path = row.path.filter(part => part !== 0).join(' › ');
    const description = [path, row.description].filter(Boolean).join('\n');
    field.classList.add('fy-option-row');
    field.replaceChildren(h('div', { className: 'fy-option-line' }, [
      trainerLockButton(row, locks),
      h('span', { className: 'fy-option-name', text: label, title: description }),
      trainerValueCell(editor),
    ]), error);
    return field;
  };
  const renderTrainerOptions = () => {
    collapseTrainerValue();
    const locks = readTrainerLocks();
    const query = state.query.trim().toLocaleLowerCase('zh-CN');
    const all = allGroups().flatMap(group => group.rows.map(row => ({ row, group: group.key })));
    const matching = all.filter(({ group, row }) => query
      ? group.toLocaleLowerCase('zh-CN').includes(query) || rowMatchesQuery(row, query)
      : trainerGroupFocus === null || group === trainerGroupFocus);
    if (!matching.length) {
      body.replaceChildren(h('div', { className: 'fy-empty' }, [h('strong', { text: 'Không có biến phù hợp' }),
        h('p', { text: 'Hãy đổi từ khóa khác, hoặc chuyển sang "Cấu trúc" để xem nhóm.' })]));
      return;
    }
    const page = matching.slice(0, trainerOptionLimit);
    const split = Math.ceil(page.length / 2);
    const makeColumn = rows => {
      const nodes = [];
      let group;
      for (const item of rows) {
        if (item.group !== group) {
          group = item.group;
          nodes.push(h('h4', { className: 'fy-option-heading', text: group }));
        }
        nodes.push(renderTrainerOption(item, locks));
      }
      return h('div', { className: 'fy-option-column' }, nodes);
    };
    body.replaceChildren(
      h('div', { className: 'fy-option-header', 'aria-hidden': 'true' }, [h('span', { text: 'Biến' }), h('span', { text: 'Giá trị hiện tại' })]),
      h('div', { className: 'fy-option-columns' }, [makeColumn(page.slice(0, split)), makeColumn(page.slice(split))]),
    );
    if (matching.length > page.length) body.append(h('button', { className: 'fy-mini fy-more-options', type: 'button',
      text: 'Hiển thị thêm (' + page.length + ' / ' + matching.length + ')', onclick: () => { trainerOptionLimit += 120; renderTrainerOptions(); } }));
  };

  // core/operations.js
  const safePreview = value => {
    if (value === undefined) return '(Không tồn tại)';
    const raw = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
    return raw.length > 900 ? `${raw.slice(0, 900)}\n…` : raw;
  };

  const editableGroupObject = (data, groupName, create = false) => {
    let group = data.stat_data[groupName];
    if (group === undefined && create) {
      group = {};
      data.stat_data[groupName] = group;
    }
    if (isValueWithDescription(group) && isPlainObject(group[0])) return group[0];
    return isPlainObject(group) ? group : null;
  };

  const rejectUnsafeSegment = segment => ['$meta', '$internal', '__proto__', 'prototype', 'constructor'].includes(String(segment)) || TRAINER_RESERVED_GROUPS.has(String(segment));

  const resolveOperationParent = (rootValue, path, create = false) => {
    if (!Array.isArray(path) || !path.length) throw new Error('Đường dẫn không được để trống');
    if (path.some(rejectUnsafeSegment)) throw new Error('Đường dẫn chứa trường được bảo vệ');
    let current = rootValue;
    for (const rawSegment of path.slice(0, -1)) {
      const segment = Array.isArray(current) && /^\d+$/.test(String(rawSegment)) ? Number(rawSegment) : rawSegment;
      if (current === null || typeof current !== 'object') throw new Error('Cấp cha của đường dẫn không phải là đối tượng hoặc mảng');
      if (!(segment in current)) {
        if (!create) throw new Error('Cấp cha của đường dẫn không tồn tại');
        current[segment] = {};
      }
      current = current[segment];
    }
    const rawKey = path.at(-1);
    const key = Array.isArray(current) && /^\d+$/.test(String(rawKey)) ? Number(rawKey) : rawKey;
    if (current === null || typeof current !== 'object') throw new Error('Cấp cha của đường dẫn không phải là đối tượng hoặc mảng');
    return { parent: current, key };
  };

  const lockedMetadataFingerprint = value => {
    const found = [];
    const walk = (node, path = []) => {
      if (!node || typeof node !== 'object') return;
      for (const [key, child] of Object.entries(node)) {
        if (key === '$meta' || key === '$internal') found.push([path.concat(key), child]);
        else walk(child, path.concat(key));
      }
    };
    walk(value);
    return stableStringify(found);
  };

  const applyOperation = (statData, operation) => {
    const path = operation.path.map(segment => typeof segment === 'number' ? segment : String(segment));
    const { parent, key } = resolveOperationParent(statData, path, operation.op === 'add');
    const exists = Array.isArray(parent) ? Number.isInteger(key) && key >= 0 && key < parent.length : Object.prototype.hasOwnProperty.call(parent, key);
    const before = exists ? clone(parent[key]) : undefined;
    if (operation.op === 'add') {
      if (exists) throw new Error('Mục tiêu add đã tồn tại');
      if (Array.isArray(parent)) {
        if (!Number.isInteger(key) || key < 0 || key > parent.length) throw new Error('Chỉ số mảng không hợp lệ');
        parent.splice(key, 0, clone(operation.value));
      } else parent[key] = clone(operation.value);
    } else if (operation.op === 'replace') {
      if (!exists) throw new Error('Mục tiêu replace không tồn tại');
      if (lockedMetadataFingerprint(before) !== lockedMetadataFingerprint(operation.value)) throw new Error('Thay thế sẽ làm thay đổi siêu dữ liệu được bảo vệ');
      parent[key] = clone(operation.value);
    } else if (operation.op === 'remove') {
      if (!exists) throw new Error('Mục tiêu remove không tồn tại');
      if (lockedMetadataFingerprint(before) !== stableStringify([])) throw new Error('Không thể xóa node chứa siêu dữ liệu được bảo vệ');
      if (Array.isArray(parent)) parent.splice(key, 1);
      else delete parent[key];
    } else throw new Error(`Thao tác không được hỗ trợ ${operation.op}`);
    const after = operation.op === 'remove' ? undefined : clone(parent[key]);
