    const cleaned = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    if (cleaned === '<NONE>') throw new Error('API trả về <NONE>: Interface không cung cấp nội dung có thể phân tích cú pháp');
    const parsed = JSON.parse(cleaned);
    if (!Array.isArray(parsed?.operations)) throw new Error('Nội dung trả về thiếu mảng operations');
    return { operations: parsed.operations, dialogue: typeof parsed.dialogue === 'string' ? parsed.dialogue.slice(0, 600) : '' };
  };

  const scopeBlockReason = operation => {
    const lock = trainerAiLockReason(operation);
    if (lock) return lock;
