      if (raw.op !== 'remove' && !Object.prototype.hasOwnProperty.call(raw, 'value')) throw new Error(`Thao tác thứ ${index + 1} thiếu value`);
      const value = raw.op === 'add' ? completeAddedObject(working, raw.path, raw.value) : raw.value;
