  // ui/ai-chat.js
  const renderFenglingChatLog = () => {
    const log = h('div', { className: 'fy-chat-log', role: 'log', 'aria-label': 'Lịch sử trò chuyện trợ lý Phong Linh Nguyệt Ảnh', 'aria-live': 'polite' });
    const bubble = (speaker, text, owner = false) => h('article', { className: `fy-chat-message${owner ? ' fy-chat-owner' : ''}` }, [
      h('span', { className: 'fy-chat-avatar', 'aria-hidden': 'true', text: owner ? 'Bạn' : null }, owner ? [] : trainerAssistantIcon('assistant')),
      h('div', { className: 'fy-chat-bubble' }, [h('small', { text: speaker }), h('p', { text })]),
    ]);
    if (!state.conversation.length && !state.aiBusy) log.append(bubble('Trợ lý Phong Linh Nguyệt Ảnh', 'Bạn muốn sửa những biến nào? Hãy nói cho tôi biết, đề xuất sẽ được đặt bên dưới để chờ bạn xác nhận.'));
    let shown = 20;
    const appendTurns = turns => turns.flatMap(turn => [bubble(`Người chơi · Tầng ${turn.floor ?? '?'}`, turn.user, true),
      bubble('Trợ lý Phong Linh Nguyệt Ảnh', turn.dialogue || (turn.result?.includes('thất bại') || turn.result?.includes('失败') ? 'Lần này không tạo được đề xuất khả dụng, vui lòng kiểm tra lỗi interface.' : 'Lần này không có phần giải thích đối thoại khả dụng.')),
      h('small', { className: 'fy-chat-result', text: `Hệ thống · ${turn.result || 'Chờ duyệt'}` })]);
    const older = h('button', { className: 'fy-mini', type: 'button', text: 'Hiển thị đối thoại sớm hơn', hidden: state.conversation.length <= shown });
    older.addEventListener('click', () => {
      const height = log.scrollHeight, top = log.scrollTop;
      const end = Math.max(0, state.conversation.length - shown), start = Math.max(0, end - 20);
      older.after(...appendTurns(state.conversation.slice(start, end))); shown += end - start;
      older.hidden = shown >= state.conversation.length;
      log.scrollTop = top + log.scrollHeight - height;
    });
    log.append(older, ...appendTurns(state.conversation.slice(-shown)));
    if (state.aiBusy) log.append(bubble('Người chơi', state.aiLastInstruction || state.aiRequest, true), bubble('Trợ lý Phong Linh Nguyệt Ảnh', 'Đang đối chiếu biến… Có thể hủy lần gọi này bất cứ lúc nào.'));
    hostWindow.setTimeout(() => { if (!state.destroyed && log.isConnected && !mobileViewport.editing()) log.scrollTop = log.scrollHeight; }, 0);
    return log;
  };

  // ui/ai-composer.js
  const renderFenglingComposer = ({ run = runFengling, ready = true, hasBody = true, inputLabel = 'Lệnh sửa đổi', extraLabel = 'Model phân tích bổ sung tầng hiện tại', groupNames = Object.keys(state.draft?.stat_data || {}).filter(key => !rejectUnsafeSegment(key)) } = {}) => {
