      if (shown > floorLimit) floorRows.append(h('button', { className: 'fy-action', type: 'button', text: `Hiển thị thêm 50 tầng (còn ${shown - floorLimit} tầng)`, onclick: () => { floorLimit += 50; renderFloors(); } }));
