    });
    floorSearch.addEventListener('compositionend', () => { floorLimit = 50; renderFloors(); });
    const clearFloors = h('button', { className: 'fy-action', type: 'button', text: 'Xóa các tầng chỉ định thủ công' });
    clearFloors.disabled = state.aiBusy;
    clearFloors.addEventListener('click', () => { state.bodyFloors.clear(); persistBodyFloors(); renderBody(); });
    floorList.append(floorSearch, clearFloors, floorRows);
    manualBodies.append(floorList);
    tokenCountLabel = h('p', { className: 'fy-help', 'aria-live': 'polite', text: 'tk đầu vào lần này: Đang thống kê…' });
    const resetChat = h('button', { className: 'fy-action fy-danger', type: 'button', text: 'Đặt lại đối thoại', title: 'Đặt lại đối thoại trợ lý' });
    resetChat.disabled = state.aiBusy;
    resetChat.addEventListener('click', resetConversation);

    const bodyCount = h('label', { className: 'fy-body-count-control', title: '0 là chỉ gửi chính văn được tích chọn thủ công' }, ['Số tầng chính văn đính kèm', bodyCountInput]);
    const commandCard = h('div', { className: 'fy-card fy-form fy-chat-card' }, [
      h('div', { className: 'fy-chat-heading' }, [h('strong', {}, [trainerAssistantIcon('assistant', 20), 'Đối thoại']), h('div', { className: 'fy-assistant-chat-tools' }, [resetChat])]),
