  // ui/ai-view.js
  const renderAiBody = () => {
    syncConversation();
    body.replaceChildren();
    if (!state.draft) return;
    if (!state.worldbookBusy && state.worldbookLoadedFor !== getContextIdentity()) hostWindow.setTimeout(() => loadBoundWorldbooks(), 0);

