    body.append(h('div', { className: 'fy-assistant-layout' }, [commandCard, side]));


    // 2. DIRECTLY BELOW COMMAND BOX: So sánh biến và đề xuất sửa đổi
    if (state.aiDiffs.length) {
      const allToggle = h('input', { type: 'checkbox', 'aria-label': 'Chọn tất cả đề xuất của trợ lý Phong Linh Nguyệt Ảnh' });
      allToggle.checked = state.aiDiffs.some(diff => !diff.blocked) && state.aiDiffs.filter(diff => !diff.blocked).every(diff => diff.selected);
      const list = h('div', { className: 'fy-diff-list' });
      const selectedCount = h('span', { className: 'fy-count' });
      const syncAll = () => {
        selectedCount.textContent = `${state.aiDiffs.filter(diff => diff.selected).length}/${state.aiDiffs.length} mục đã chọn`;
        allToggle.checked = state.aiDiffs.some(diff => !diff.blocked) && state.aiDiffs.filter(diff => !diff.blocked).every(diff => diff.selected);
        allToggle.indeterminate = state.aiDiffs.some(diff => diff.selected) && !allToggle.checked;
        allToggle.disabled = !state.aiDiffs.some(diff => !diff.blocked);
        apply.disabled = !state.aiDiffs.some(diff => diff.selected && !diff.blocked && !scopeBlockReason(diff.operation));
      };
      allToggle.addEventListener('change', () => {
        state.aiDiffs.forEach(diff => { diff.selected = !diff.blocked && allToggle.checked; });
