  // +trainer-prompt-settings.js
  const renderPromptInsertionBody = () => {
    const { scope, config, presets } = trainerPromptSnapshot();
    body.replaceChildren();
    const controls = {};
    const sync = () => {
      for (const key of trainerPromptKinds) config[key] = { enabled: controls[key].toggle.checked, text: controls[key].text.value };
      return updateTrainerPrompts(scope, config);
    };
    const paint = () => {
      for (const key of trainerPromptKinds) {
        controls[key].toggle.checked = config[key].enabled;
        controls[key].text.value = config[key].text;
      }
    };
    for (const [key, title, placeholder] of [
      ['body', 'Chính văn', 'Điền yêu cầu tạo chính văn…'],
      ['variable', 'MVU · Phân tích bổ sung', 'Điền yêu cầu bổ sung cho model phân tích bổ sung…'],
      ['database', 'Cơ sở dữ liệu · Mỗi lần điền bảng', 'Điền yêu cầu bổ sung khi điền bảng tự động và thủ công…'],
    ]) {
      const toggle = h('input', { type: 'checkbox', 'aria-label': 'Bật prompt ' + title, disabled: scope ? null : true });
      const text = h('textarea', { className: 'fy-textarea', maxlength: '12000', placeholder, 'aria-label': 'Prompt ' + title, disabled: scope ? null : true });
      toggle.addEventListener('change', sync);
      text.addEventListener('input', sync);
      text.addEventListener('blur', () => flushTrainerPrompts());
      controls[key] = { toggle, text };
      body.append(h('section', { className: 'fy-card fy-form fy-compact-settings', hidden: key === 'database' && !trainerDatabaseAvailable ? true : null }, [
        h('label', { className: 'fy-setting-choice fy-prompt-heading' }, [toggle, title]), text,
      ]));
    }
    paint();
    if (!scope) { body.append(h('p', { className: 'fy-help', text: 'Vui lòng mở một cuộc trò chuyện trước.' })); return; }
    const select = h('select', { className: 'fy-select', 'aria-label': 'Tải preset' }, [
      h('option', { value: '', text: 'Tải preset' }), ...presets.map((item, index) => h('option', { value: String(index), text: item.name })),
    ]);
    const name = h('input', { className: 'fy-input', placeholder: 'Tên preset', 'aria-label': 'Tên preset', maxlength: '80' });
    select.addEventListener('change', () => {
