    ])) listen(name, () => { if (state.open) scheduleRefresh({ delay: 220 }); });
    listen(events.GENERATION_STARTED ?? 'generation_started', (_type, _options, dryRun) => {
      if (dryRun) return;
      state.generating = true;
      setStatus('Đang tạo phản hồi, tạm thời không thể lưu', 'warning');
      updateControls();
    });
    const ended = () => {
      state.generating = false;
      clearPromptInsertion();
      updateControls();
      if (state.open) scheduleRefresh();
    };
    listen(events.GENERATION_ENDED ?? 'generation_ended', ended);
    listen(events.GENERATION_STOPPED ?? 'generation_stopped', ended);
    state.pollTimer = hostWindow.setInterval(() => {
      if (!state.open || state.generating || state.saving || state.aiBusy || state.apiModelsBusy || hostDocument.hidden || mobileViewport.editing()) return;
      if (refreshTrainerDatabaseAvailability()) { renderBody(); updateControls(); }
      if (!trainerDatabasePageActive()) void loadLatest();
    }, 1500);
    refreshTrainerDatabaseAvailability();
    updateControls();
    renderBody();
    applyLayout();
  };
  window.addEventListener('pagehide', destroy, { once: true });
  window.addEventListener('beforeunload', destroy, { once: true });
  boot();
})();
